const envelope = $json;
if (!envelope || envelope.type !== 'fan.confirmed' || envelope.version !== 1) throw new Error('Unsupported CrowdRelay event');
const data = envelope.data ?? {};
for (const key of ['email', 'referral_code', 'unsubscribe_token']) {
  if (data[key] === undefined || data[key] === null || data[key] === '') throw new Error(`Missing confirmed fan field: ${key}`);
}
const base = ("https://virya.music" || '').replace(/\/$/, '');
if (!base) throw new Error('Missing CROWDRELAY_PUBLIC_SITE_URL');
return [{ json: { event_id: envelope.id, mail: {
  template: 'crowdrelay-fan-welcome', to: data.email,
  variables: { display_name: data.display_name ?? null, referral_url: `${base}/r/${encodeURIComponent(data.referral_code)}`, my_signal_url: `${base}/my-signal`, unsubscribe_url: `${base}/signal/unsubscribe#token=${encodeURIComponent(data.unsubscribe_token)}` },
  idempotency_key: envelope.id
} } }];
